from fastapi import FastAPI, HTTPException, WebSocket, WebSocketDisconnect
from fastapi.exceptions import RequestValidationError, ResponseValidationError, WebSocketRequestValidationError
from pydantic import BaseModel
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

class Item(BaseModel):
    id: int
    name: str

@app.get("/users/{user_id}")
async def get_user(user_id: int):
    return {"user_id": user_id}

@app.post("/items/")
async def create_item(item: Item):
    # To trigger ResponseValidationError, we return something that doesn't match the response model
    # But we need to specify response_model for ResponseValidationError to be raised
    return {"name": "Widget"} # missing 'id'

# To trigger ResponseValidationError, we need to use response_model
@app.post("/items_resp/", response_model=Item)
async def create_item_resp(item: Item):
    return {"name": "Widget"} # missing 'id'

@app.websocket("/ws/{item_id}")
async def websocket_endpoint(websocket: WebSocket, item_id: int):
    await websocket.accept()
    await websocket.send_text(f"Item {item_id}")
    await websocket.close()

client = TestClient(app)

def test_request_validation_error():
    try:
        # This should trigger RequestValidationError
        client.get("/users/invalid")
    except RequestValidationError as e:
        print(f"Caught RequestValidationError: {e}")
    except Exception as e:
        print(f"Caught other exception: {type(e).__name__}: {e}")

def test_response_validation_error():
    try:
        # This should trigger ResponseValidationError
        client.post("/items_resp/", json={"id": 1, "name": "Widget"})
    except ResponseValidationError as e:
        print(f"Caught ResponseValidationError: {e}")
    except Exception as e:
        print(f"Caught other exception: {type(e).__name__}: {e}")

def test_websocket_validation_error():
    try:
        # This should trigger WebSocketRequestValidationError
        client.websocket_connect("/ws/invalid")
